    "definitionSimple": "Because of the Fall, every part of human nature (mind, will, heart) is affected by sin, making us unable to save ourselves.",
    "definitionStudy": "The doctrine that original sin extends to every faculty of humanity, rendering persons spiritually dead and incapable of choosing God apart from regenerating grace.",
    "definitionAcademic": "The anthropological axiom (corruptio totalis) stating that the post-lapsarian state involves complete privation of original righteousness, not that man is as evil as possible, but that sin pervasively disables moral agency toward salvation.",
    "biblicalUsage": "Romans 3:10-18; Jeremiah 17:9; Ephesians 2:1-3; Genesis 6:5.",
    "scriptureReferences": [
      "Romans 3:10-12",
      "Jeremiah 17:9",
      "Ephesians 2:1-3",
      "1 Corinthians 2:14"
    ],
    "historicalDevelopment": "Augustine in anti-Pelagian treatises; reiterated by Luther (Bondage of the Will), Calvin, and Canons of Dort ('T' in TULIP).",
    "theologicalSignificance": "Establishes the absolute necessity of monergistic grace for salvation.",
