    "historicalDevelopment": "Affirmed at Chalcedon (451 AD) overcoming Nestorianism (division of persons) and Eutychianism/Monophysitism (confusion of natures).",
    "theologicalSignificance": "Essential for mediation; as man He could represent us, and as God His sacrifice has infinite value.",
