    "definitionStudy": "The divine attribute whereby God perfectly, exhaustively, and simultaneously knows Himself, all actual reality, and all potential possibilities without learning (Ps 139:1-6; 1 John 3:20).",
    "definitionAcademic": "The cognitive perfection of the divine essence (scientia Dei) characterized by intuitive, eternal, and simultaneous apprehension of all entities (scientia visionis) and all counterfactual contingencies (scientia media).",
