    "definitionSimple": "The miraculous ability given by the Holy Spirit to speak in a real, foreign human language that the speaker never learned.",
    "definitionStudy": "The Pentecost miracle in Acts 2:4-11 where disciples spoke in actual known human languages (xenoglossia), enabling visitors from many nations to hear God's mighty works in their own native tongues.",
    "definitionAcademic": "The pneumatological phenomenon distinguished from ecstatic glossolalia, signifying the reversal of Babel and the prophetic inauguration of the multi-ethnic, global mission of the Church.",
